package main

import (
	"net/http"
	"net/http/httptest"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestProbeRateLimit(t *testing.T) {
	store := NewStore(time.Minute)
	handler := sessionHandler(store)
	now := time.Unix(1000, 0)
	nowFunc = func() time.Time { return now }

	post := func(id string) int {
		rec := httptest.NewRecorder()
		req := httptest.NewRequest("POST", "/session?id="+id+"&user=u", nil)
		req.Header.Set("Content-Type", "application/json")
		handler(rec, req)
		return rec.Code
	}

	if code := post("rl1"); code != http.StatusOK {
		t.Fatalf("first create = %d, want 200", code)
	}
	if code := post("rl1"); code != http.StatusTooManyRequests {
		t.Fatalf("immediate recreate = %d, want 429", code)
	}
	// A different id is not limited by rl1's window.
	if code := post("rl2"); code != http.StatusOK {
		t.Fatalf("different id = %d, want 200", code)
	}
	// After the 1s window, rl1 is allowed again.
	nowFunc = func() time.Time { return time.Unix(1001, 1) }
	if code := post("rl1"); code != http.StatusOK {
		t.Fatalf("post-window create = %d, want 200", code)
	}

	// Concurrent safety: 50 goroutines hammering one id; exactly one wins.
	conc := NewStore(time.Minute)
	handler2 := sessionHandler(conc)
	nowFunc = func() time.Time { return time.Unix(5000, 0) }
	var wg sync.WaitGroup
	var accepted int32
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			rec := httptest.NewRecorder()
			req := httptest.NewRequest("POST", "/session?id=hot&user=u", nil)
			req.Header.Set("Content-Type", "application/json")
			handler2(rec, req)
			if rec.Code == http.StatusOK {
				atomic.AddInt32(&accepted, 1)
			}
		}()
	}
	wg.Wait()
	if atomic.LoadInt32(&accepted) != 1 {
		t.Fatalf("accepted = %d, want exactly 1", atomic.LoadInt32(&accepted))
	}
}
EOF
go test -race -count=1 . ; rc=$? ; rm -f probe_ratelimit_test.go ; exit $rc

